/**
 * ESM form of the @deepseek-ai/dsh-llm/message surface (real package is ESM:
 * "type":"module", lib/message.js is ESM). Surface copied verbatim from the dsh
 * source: packages/llm/llm/src/message.ts (isTokenDelta) + brand.ts (MessageId).
 * Only the members the dsh plugins in this spike import are provided.
 */

/** Provider/model identity — brand string (message.ts MessageId / brand.ts). */
export function MessageId(id) { return id }

/**
 * Whether a stream chunk carries visible model output (the first-token
 * boundary shared by client step timing and the whole-log sessionStats
 * projection). Empty deltas (heartbeats, empty tool-call frames) do not count
 * as a first token.
 * @param chunk - the stream chunk to test.
 * @returns true when the chunk contains a non-empty text/reasoning/tool delta.
 */
export function isTokenDelta(chunk) {
  switch (chunk.type) {
    case 'text-delta':
    case 'reasoning-delta':
      return chunk.text !== ''
    case 'tool-call-delta':
      return chunk.argumentsDelta !== '' || chunk.name !== undefined
    default:
      return false
  }
}

/** Create one identified user-role message and freeze it (message.ts:192-199). */
export function createUserMessage(input) {
  const id = (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function')
    ? crypto.randomUUID()
    : ('esm-' + Math.random().toString(36).slice(2))
  return Object.freeze({
    ...input,
    id: MessageId(id),
    role: 'user',
  })
}

/** Detach and deep-freeze a message whose identity already exists (message.ts:169-171). */
export function freezeMessage(message) {
  return Object.freeze(structuredClone(message))
}
